'use client';import {useState} from 'react';import {Eye,MessageCircle,Pencil,Trash2,Printer} from 'lucide-react';import {Bill,money,WA_NUMBER} from '@/lib/data';import {useStore} from '@/lib/store';import {Panel,Toolbar} from '@/components/Panel';
export default function Bills(){const{bills,setBills,role,toast}=useStore();const[q,setQ]=useState('');const[v,setV]=useState<Bill|null>(null);const data=bills.filter(b=>(b.billNo+' '+b.customer.name+' '+b.customer.mobile).toLowerCase().includes(q.toLowerCase()));function share(b:Bill){const text=`Noor Collections\n${b.billNo}\nCustomer: ${b.customer.name}\n${b.items.map(i=>`${i.name} x ${i.qty} = ${money(i.total)}`).join('\n')}\nTotal Amount: ${money(b.subtotal)}\nPaid: ${money(b.paid)}\nBalance: ${money(b.balance)}`;navigator.clipboard?.writeText(text);toast('Bill copied to clipboard');window.open(`https://wa.me/${WA_NUMBER}?text=${encodeURIComponent(text)}`,'_blank')}function del(id:number){if(confirm('Delete this bill?')){setBills(v=>v.filter(b=>b.id!==id));toast('Bill deleted')}}return <><Toolbar title="Bills & History" subtitle="View, print, share or delete completed bills"/><Panel><div className="filterbar"><div className="search-box dark"><input value={q} onChange={e=>setQ(e.target.value)} placeholder="Search bill, customer or mobile..."/></div></div><div className="table-card"><table><thead><tr><th>Bill No</th><th>Customer</th><th>Mobile</th><th>Total Amount</th><th>Payment</th>{role==='admin'&&<><th>Expense</th><th>Profit</th></>}<th>Date</th><th>Action</th></tr></thead><tbody>{data.map(b=><tr key={b.id}><td><b>{b.billNo}</b></td><td>{b.customer.name}</td><td>{b.customer.mobile}</td><td>{money(b.subtotal)}</td><td>{b.payment}</td>{role==='admin'&&<><td>{money(b.expense)}</td><td>{money(b.profit)}</td></>}<td>{b.date}</td><td><div className="row-actions"><button onClick={()=>setV(b)}><Eye size={15}/></button><button onClick={()=>share(b)}><MessageCircle size={15}/></button><button className="danger" onClick={()=>del(b.id)}><Trash2 size={15}/></button></div></td></tr>)}</tbody></table>{!data.length&&<p className="empty">No bills found.</p>}</div></Panel>{v&&<div className="overlay"><div className="receipt-modal"><div className="receipt-actions"><button className="primary-btn" onClick={()=>window.print()}><Printer/>Print</button><button className="wa-btn" onClick={()=>share(v)}><MessageCircle/>Share on WhatsApp</button><button onClick={()=>setV(null)}>×</button></div><div className="receipt"><h2>Noor Collections</h2><p>SALES RECEIPT</p><hr/><p>Bill No: <b>{v.billNo}</b></p><p>Customer: <b>{v.customer.name}</b> · {v.customer.mobile}</p><table><thead><tr><th>Product</th><th>Qty</th><th>Price</th><th>Total</th></tr></thead><tbody>{v.items.map(i=><tr key={i.productId}><td>{i.name}</td><td>{i.qty}</td><td>{money(i.price)}</td><td>{money(i.total)}</td></tr>)}</tbody></table><div className="receipt-total"><span>Total Amount</span><b>{money(v.subtotal)}</b><span>Paid</span><b>{money(v.paid)}</b><span>Balance</span><b>{money(v.balance)}</b></div></div></div></div>}</>}
